using UnityEngine;\nusing System.Collections.Generic;\n\n/// <summary>\n/// File cấu hình tập trung - Quản lý toàn bộ cài đặt game\n/// Bao gồm: Rung, FPS, Hiệu năng, Đồ họa\n/// </summary>\npublic class GameConfig : MonoBehaviour\n{\n    private static GameConfig instance;\n\n    [System.Serializable]\n    public class DeviceProfile\n    {\n        public string profileName = \"Weak\";\n        public int targetFPS = 30;\n        public int qualityLevel = 0;\n        public int shadowCascades = 1;\n        public float shadowDistance = 30f;\n        public ShadowQuality shadowQuality = ShadowQuality.HardOnly;\n        public AnisotropicFiltering anisotropicFiltering = AnisotropicFiltering.Disable;\n        public int antiAliasing = 0;\n        public int vSyncCount = 0;\n        public float vibrationIntensity = 0.3f;\n        public float fixedDeltaTime = 0.02f;\n        public int solverIterations = 3;\n        public int solverVelocityIterations = 1;\n    }\n\n    [SerializeField] private bool autoDetectDevice = true;\n    [SerializeField] private int manualDeviceLevel = 0; // 0=Yếu, 1=Bình thường, 2=Mạnh\n    [SerializeField] private List<DeviceProfile> deviceProfiles = new List<DeviceProfile>();\n\n    private int currentDeviceLevel = 0;\n    private DeviceProfile currentProfile;\n    private bool isVibrationEnabled = true;\n    private bool isOptimizationEnabled = true;\n    private bool isFPSLocked = true;\n\n    void Awake()\n    {\n        if (instance == null)\n        {\n            instance = this;\n            DontDestroyOnLoad(gameObject);\n            InitializeConfig();\n        }\n        else\n        {\n            Destroy(gameObject);\n        }\n    }\n\n    void Start()\n    {\n        ApplyConfiguration();\n    }\n\n    /// <summary>\n    /// Khởi tạo cấu hình mặc định\n    /// </summary>\n    void InitializeConfig()\n    {\n        // Xóa danh sách cũ\n        if (deviceProfiles == null) deviceProfiles = new List<DeviceProfile>();\n        deviceProfiles.Clear();\n\n        // Profile 0: Máy Yếu (1-2 nhân, <2GB RAM)\n        DeviceProfile weakProfile = new DeviceProfile\n        {\n            profileName = \"Weak Device\",\n            targetFPS = 30,\n            qualityLevel = 0,\n            shadowCascades = 1,\n            shadowDistance = 30f,\n            shadowQuality = ShadowQuality.HardOnly,\n            anisotropicFiltering = AnisotropicFiltering.Disable,\n            antiAliasing = 0,\n            vSyncCount = 0,\n            vibrationIntensity = 0.3f,\n            fixedDeltaTime = 0.02f,\n            solverIterations = 3,\n            solverVelocityIterations = 1\n        };\n        deviceProfiles.Add(weakProfile);\n\n        // Profile 1: Máy Bình Thường (4 nhân, 2-4GB RAM)\n        DeviceProfile mediumProfile = new DeviceProfile\n        {\n            profileName = \"Medium Device\",\n            targetFPS = 45,\n            qualityLevel = 2,\n            shadowCascades = 2,\n            shadowDistance = 50f,\n            shadowQuality = ShadowQuality.All,\n            anisotropicFiltering = AnisotropicFiltering.Enable,\n            antiAliasing = 2,\n            vSyncCount = 0,\n            vibrationIntensity = 0.6f,\n            fixedDeltaTime = 0.02f,\n            solverIterations = 6,\n            solverVelocityIterations = 2\n        };\n        deviceProfiles.Add(mediumProfile);\n\n        // Profile 2: Máy Mạnh (4+ nhân, >4GB RAM)\n        DeviceProfile strongProfile = new DeviceProfile\n        {\n            profileName = \"Strong Device\",\n            targetFPS = 60,\n            qualityLevel = 4,\n            shadowCascades = 3,\n            shadowDistance = 100f,\n            shadowQuality = ShadowQuality.All,\n            anisotropicFiltering = AnisotropicFiltering.Enable,\n            antiAliasing = 4,\n            vSyncCount = 1,\n            vibrationIntensity = 1f,\n            fixedDeltaTime = 0.01667f,\n            solverIterations = 7,\n            solverVelocityIterations = 2\n        };\n        deviceProfiles.Add(strongProfile);\n    }\n\n    /// <summary>\n    /// Phát hiện và áp dụng cấu hình cho thiết bị\n    /// </summary>\n    void ApplyConfiguration()\n    {\n        if (autoDetectDevice)\n        {\n            currentDeviceLevel = DetectDevicePerformance();\n        }\n        else\n        {\n            currentDeviceLevel = manualDeviceLevel;\n        }\n\n        if (currentDeviceLevel >= 0 && currentDeviceLevel < deviceProfiles.Count)\n        {\n            currentProfile = deviceProfiles[currentDeviceLevel];\n            Debug.Log($\"[GameConfig] Áp dụng profile: {currentProfile.profileName}\");\n        }\n        else\n        {\n            Debug.LogError(\"[GameConfig] Không tìm thấy profile phù hợp!\");\n            return;\n        }\n\n        // Áp dụng tất cả cài đặt\n        if (isOptimizationEnabled)\n        {\n            ApplyGraphicsSettings();\n            ApplyPhysicsSettings();\n        }\n\n        if (isFPSLocked)\n        {\n            LockFPS();\n        }\n    }\n\n    /// <summary>\n    /// Phát hiện hiệu năng thiết bị\n    /// </summary>\n    int DetectDevicePerformance()\n    {\n        int processorCount = SystemInfo.processorCount;\n        int systemMemorySize = SystemInfo.systemMemorySize;\n\n        Debug.Log($\"[GameConfig] CPU Cores: {processorCount} | RAM: {systemMemorySize}MB\");\n\n        if (processorCount <= 2 || systemMemorySize < 2048)\n        {\n            return 0; // Yếu\n        }\n        else if (processorCount <= 4 || systemMemorySize < 4096)\n        {\n            return 1; // Bình thường\n        }\n        else\n        {\n            return 2; // Mạnh\n        }\n    }\n\n    /// <summary>\n    /// Áp dụng cài đặt đồ họa\n    /// </summary>\n    void ApplyGraphicsSettings()\n    {\n        QualitySettings.SetQualityLevel(currentProfile.qualityLevel, true);\n        QualitySettings.vSyncCount = currentProfile.vSyncCount;\n        QualitySettings.shadowCascades = currentProfile.shadowCascades;\n        QualitySettings.shadowDistance = currentProfile.shadowDistance;\n        QualitySettings.shadows = currentProfile.shadowQuality;\n        QualitySettings.anisotropicFiltering = currentProfile.anisotropicFiltering;\n        QualitySettings.antiAliasing = currentProfile.antiAliasing;\n        QualitySettings.realtimeReflectionProbes = (currentProfile.qualityLevel >= 2);\n        QualitySettings.billboardsFaceCameraPosition = (currentProfile.qualityLevel >= 2);\n\n        Debug.Log($\"[Graphics] Quality Level: {currentProfile.qualityLevel} | AA: {currentProfile.antiAliasing}x\");\n    }\n\n    /// <summary>\n    /// Áp dụng cài đặt vật lý\n    /// </summary>\n    void ApplyPhysicsSettings()\n    {\n        Time.fixedDeltaTime = currentProfile.fixedDeltaTime;\n        Physics.defaultSolverIterations = currentProfile.solverIterations;\n        Physics.defaultSolverVelocityIterations = currentProfile.solverVelocityIterations;\n\n        Debug.Log($\"[Physics] FixedDeltaTime: {currentProfile.fixedDeltaTime} | Solver Iterations: {currentProfile.solverIterations}\");\n    }\n\n    /// <summary>\n    /// Khóa FPS theo cấu hình\n    /// </summary>\n    void LockFPS()\n    {\n        QualitySettings.targetFrameRate = currentProfile.targetFPS;\n        Debug.Log($\"[FPS] Khóa FPS tại: {currentProfile.targetFPS}\");\n    }\n\n    /// <summary>\n    /// Bật/Tắt rung\n    /// </summary>\n    public void SetVibrationEnabled(bool enabled)\n    {\n        isVibrationEnabled = enabled;\n        if (VibrationManager.Instance != null)\n        {\n            VibrationManager.Instance.SetVibrationEnabled(enabled);\n        }\n        Debug.Log($\"[Vibration] Rung: {(enabled ? \"BẬT\" : \"TẮT\")}\");\n    }\n\n    /// <summary>\n    /// Bật/Tắt tối ưu hóa\n    /// </summary>\n    public void SetOptimizationEnabled(bool enabled)\n    {\n        isOptimizationEnabled = enabled;\n        if (enabled)\n        {\n            ApplyConfiguration();\n        }\n        Debug.Log($\"[Optimization] Tối ưu hóa: {(enabled ? \"BẬT\" : \"TẮT\")}\");\n    }\n\n    /// <summary>\n    /// Bật/Tắt khóa FPS\n    /// </summary>\n    public void SetFPSLocked(bool locked)\n    {\n        isFPSLocked = locked;\n        if (locked)\n        {\n            LockFPS();\n        }\n        else\n        {\n            QualitySettings.targetFrameRate = -1; // Không giới hạn\n            Debug.Log(\"[FPS] Tắt khóa FPS\");\n        }\n    }\n\n    /// <summary>\n    /// Lấy FPS hiện tại\n    /// </summary>\n    public int GetTargetFPS()\n    {\n        return currentProfile.targetFPS;\n    }\n\n    /// <summary>\n    /// Lấy mức hiệu năng thiết bị (0=Yếu, 1=Bình thường, 2=Mạnh)\n    /// </summary>\n    public int GetDeviceLevel()\n    {\n        return currentDeviceLevel;\n    }\n\n    /// <summary>\n    /// Lấy tên profile hiện tại\n    /// </summary>\n    public string GetProfileName()\n    {\n        return currentProfile.profileName;\n    }\n\n    /// <summary>\n    /// Lấy cường độ rung hiện tại\n    /// </summary>\n    public float GetVibrationIntensity()\n    {\n        return currentProfile.vibrationIntensity;\n    }\n\n    /// <summary>\n    /// Cấu hình thủ công cho thiết bị cụ thể\n    /// </summary>\n    public void SetCustomProfile(int deviceLevel)\n    {\n        if (deviceLevel >= 0 && deviceLevel < deviceProfiles.Count)\n        {\n            autoDetectDevice = false;\n            manualDeviceLevel = deviceLevel;\n            ApplyConfiguration();\n            Debug.Log($\"[GameConfig] Đã thiết lập profile thủ công: {GetProfileName()}\");\n        }\n    }\n\n    /// <summary>\n    /// Hiển thị thông tin cấu hình hiện tại\n    /// </summary>\n    public void LogCurrentConfig()\n    {\n        Debug.Log($\"\"\"\n=== GAME CONFIG ===\nProfile: {currentProfile.profileName}\nDevice Level: {currentDeviceLevel}\nTarget FPS: {currentProfile.targetFPS}\nQuality Level: {currentProfile.qualityLevel}\nVibration Intensity: {currentProfile.vibrationIntensity}\nVibration Enabled: {isVibrationEnabled}\nOptimization Enabled: {isOptimizationEnabled}\nFPS Locked: {isFPSLocked}\n==================\n        \"\"\");\n    }\n\n    /// <summary>\n    /// Rung nhẹ (bắn súng)\n    /// </summary>\n    public void PlayLightVibration()\n    {\n        if (isVibrationEnabled && VibrationManager.Instance != null)\n        {\n            VibrationManager.Instance.LightVibration();\n        }\n    }\n\n    /// <summary>\n    /// Rung trung bình (trúng đích)\n    /// </summary>\n    public void PlayMediumVibration()\n    {\n        if (isVibrationEnabled && VibrationManager.Instance != null)\n        {\n            VibrationManager.Instance.MediumVibration();\n        }\n    }\n\n    /// <summary>\n    /// Rung mạnh (trúng kẻ địch)\n    /// </summary>\n    public void PlayHardVibration()\n    {\n        if (isVibrationEnabled && VibrationManager.Instance != null)\n        {\n            VibrationManager.Instance.HardVibration();\n        }\n    }\n\n    /// <summary>\n    /// Rung cảnh báo\n    /// </summary>\n    public void PlayWarningVibration()\n    {\n        if (isVibrationEnabled && VibrationManager.Instance != null)\n        {\n            VibrationManager.Instance.WarningVibration();\n        }\n    }\n\n    public static GameConfig Instance => instance;\n    public bool IsVibrationEnabled => isVibrationEnabled;\n    public bool IsOptimizationEnabled => isOptimizationEnabled;\n    public bool IsFPSLocked => isFPSLocked;\n}\n